import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 21;
    static final double TOLERANCE = 1e-6;
    static int totalCount = 0, kValue, totalM;
    static double[] probabilities = new double[MAXN];
    static int[] indices = new int[MAXN];
    static double[] answer;
    static double[] dp = new double[1 << MAXN];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        totalM = Integer.parseInt(st.nextToken());
        kValue = Integer.parseInt(st.nextToken());
        answer = new double[totalM];

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < totalM; i++) {
            double val = Double.parseDouble(st.nextToken());
            if (val > TOLERANCE) {
                probabilities[totalCount] = val;
                indices[totalCount] = i;
                totalCount++;
            } else {
                answer[i] = 0.0;
            }
        }

        solve();

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < totalM; i++) {
            sb.append(answer[i]).append(" ");
        }
        System.out.println(sb.toString().trim());
    }

    static void solve() {
        if (kValue >= totalCount) {
            for (int i = 0; i < totalCount; i++) {
                answer[indices[i]] = 1.0;
            }
        } else {
            Arrays.fill(dp, 0.0);
            dp[0] = 1.0;
            int totalStates = 1 << totalCount;
            for (int mask = 0; mask < totalStates; mask++) {
                if (Integer.bitCount(mask) < kValue) {
                    double sum_probs = 0.0;
                    for (int t = 0; t < totalCount; t++) {
                        if (((mask >> t) & 1) == 0) {
                            sum_probs += probabilities[t];
                        }
                    }
                    if (sum_probs > 0) {
                        for (int t = 0; t < totalCount; t++) {
                            if (((mask >> t) & 1) == 0) {
                                int nextMask = mask | (1 << t);
                                dp[nextMask] += (probabilities[t] / sum_probs) * dp[mask];
                            }
                        }
                    }
                }
            }
            for (int mask = 0; mask < totalStates; mask++) {
                if (Integer.bitCount(mask) == kValue) {
                    for (int t = 0; t < totalCount; t++) {
                        if (((mask >> t) & 1) == 1) {
                            answer[indices[t]] += dp[mask];
                        }
                    }
                }
            }
        }
    }
}
